/*
 * Self-contained canvas line chart for the P9 monitoring terminal.
 *
 * NOTE: This is NOT the upstream uPlot library. This offline build environment has
 * no network/CDN access, so the real uPlot binary could not be vendored. This file
 * provides a small, dependency-free equity/line chart that satisfies the same
 * "no CDN / no npm / no build" constraint. If you want the real uPlot, drop its
 * uPlot.min.js + uPlot.min.css into this vendor/ directory and adapt app.js.
 *
 * Exposes: window.EquityChart(canvasEl, opts) -> { update(series, opts), destroy() }
 *   opts: { color, fill, baseline (number|null), baselineColor, xlabel }
 * Deliberately tiny; canvas-only; no external dependencies; MIT-style.
 */
(function () {
  "use strict";

  function fmt(v) {
    if (v == null || !isFinite(v)) return "—";
    var a = Math.abs(v);
    if (a >= 1e9) return (v / 1e9).toFixed(2) + "B";
    if (a >= 1e6) return (v / 1e6).toFixed(2) + "M";
    if (a >= 1e3) return (v / 1e3).toFixed(2) + "K";
    return v.toFixed(2);
  }

  function EquityChart(canvas, opts) {
    opts = opts || {};
    var ctx = canvas.getContext("2d");
    var series = [];
    var conf = {
      color: opts.color || "#3fb950",
      fill: opts.fill || "rgba(63,185,80,0.10)",
      baseline: opts.baseline != null ? opts.baseline : null,
      baselineColor: opts.baselineColor || "rgba(139,148,158,0.45)",
      xlabel: opts.xlabel || "Validation boundary",
    };
    var hover = -1;

    function css() {
      return getComputedStyle(document.documentElement);
    }

    function draw() {
      var dpr = window.devicePixelRatio || 1;
      var w = canvas.clientWidth || 600;
      var h = canvas.clientHeight || 260;
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      var vars = css();
      var grid = (vars.getPropertyValue("--grid") || "#20242c").trim();
      var muted = (vars.getPropertyValue("--muted") || "#8b949e").trim();
      var padL = 62, padR = 14, padT = 14, padB = 26;
      var plotW = Math.max(1, w - padL - padR);
      var plotH = Math.max(1, h - padT - padB);

      var vals = series.filter(function (v) { return v != null && isFinite(v); });
      if (vals.length === 0) {
        ctx.fillStyle = muted;
        ctx.font = "12px ui-monospace, monospace";
        ctx.textAlign = "center";
        ctx.fillText("No data yet", w / 2, h / 2);
        return;
      }

      var lo = Math.min.apply(null, vals);
      var hi = Math.max.apply(null, vals);
      if (conf.baseline != null && isFinite(conf.baseline)) {
        lo = Math.min(lo, conf.baseline);
        hi = Math.max(hi, conf.baseline);
      }
      if (hi === lo) { hi += 1; lo -= 1; }
      var pad = (hi - lo) * 0.08;
      lo -= pad; hi += pad;

      var n = series.length;
      function X(i) { return padL + (n <= 1 ? plotW / 2 : (i / (n - 1)) * plotW); }
      function Y(v) { return padT + plotH - ((v - lo) / (hi - lo)) * plotH; }

      // gridlines + y labels
      ctx.strokeStyle = grid;
      ctx.fillStyle = muted;
      ctx.lineWidth = 1;
      ctx.font = "11px ui-monospace, monospace";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      var ticks = 4;
      for (var t = 0; t <= ticks; t++) {
        var val = lo + (hi - lo) * (t / ticks);
        var y = Y(val);
        ctx.globalAlpha = 0.5;
        ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(w - padR, y); ctx.stroke();
        ctx.globalAlpha = 1;
        ctx.fillText(fmt(val), padL - 8, y);
      }

      // baseline (starting equity)
      if (conf.baseline != null && isFinite(conf.baseline)) {
        var by = Y(conf.baseline);
        ctx.save();
        ctx.strokeStyle = conf.baselineColor;
        ctx.setLineDash([4, 4]);
        ctx.beginPath(); ctx.moveTo(padL, by); ctx.lineTo(w - padR, by); ctx.stroke();
        ctx.restore();
      }

      // area fill
      ctx.beginPath();
      ctx.moveTo(X(0), Y(series[0]));
      for (var i = 1; i < n; i++) ctx.lineTo(X(i), Y(series[i]));
      ctx.lineTo(X(n - 1), padT + plotH);
      ctx.lineTo(X(0), padT + plotH);
      ctx.closePath();
      ctx.fillStyle = conf.fill;
      ctx.fill();

      // line
      ctx.beginPath();
      ctx.moveTo(X(0), Y(series[0]));
      for (var j = 1; j < n; j++) ctx.lineTo(X(j), Y(series[j]));
      ctx.strokeStyle = conf.color;
      ctx.lineWidth = 1.6;
      ctx.stroke();

      // last point marker
      ctx.fillStyle = conf.color;
      ctx.beginPath();
      ctx.arc(X(n - 1), Y(series[n - 1]), 2.6, 0, Math.PI * 2);
      ctx.fill();

      // x label
      ctx.fillStyle = muted;
      ctx.textAlign = "center";
      ctx.textBaseline = "alphabetic";
      ctx.fillText(conf.xlabel + " →", w / 2, h - 8);

      // hover crosshair + tooltip
      if (hover >= 0 && hover < n && series[hover] != null) {
        var hx = X(hover), hy = Y(series[hover]);
        ctx.strokeStyle = "rgba(139,148,158,0.35)";
        ctx.setLineDash([2, 3]);
        ctx.beginPath(); ctx.moveTo(hx, padT); ctx.lineTo(hx, padT + plotH); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = conf.color;
        ctx.beginPath(); ctx.arc(hx, hy, 3.2, 0, Math.PI * 2); ctx.fill();
        var label = "#" + hover + "  " + fmt(series[hover]);
        ctx.font = "11px ui-monospace, monospace";
        var tw = ctx.measureText(label).width + 12;
        var tx = Math.min(Math.max(hx - tw / 2, padL), w - padR - tw);
        ctx.fillStyle = "rgba(13,17,23,0.92)";
        ctx.strokeStyle = grid;
        ctx.beginPath(); ctx.rect(tx, padT + 2, tw, 18); ctx.fill(); ctx.stroke();
        ctx.fillStyle = "#e6edf3";
        ctx.textAlign = "left";
        ctx.fillText(label, tx + 6, padT + 14);
      }
    }

    function onMove(ev) {
      var rect = canvas.getBoundingClientRect();
      var x = ev.clientX - rect.left;
      var w = canvas.clientWidth;
      var padL = 62, padR = 14;
      var n = series.length;
      if (n === 0) return;
      var rel = (x - padL) / Math.max(1, w - padL - padR);
      hover = Math.round(rel * (n - 1));
      if (hover < 0) hover = 0;
      if (hover > n - 1) hover = n - 1;
      draw();
    }
    function onLeave() { hover = -1; draw(); }

    canvas.addEventListener("mousemove", onMove);
    canvas.addEventListener("mouseleave", onLeave);
    var ro = null;
    if (window.ResizeObserver) {
      ro = new ResizeObserver(function () { draw(); });
      ro.observe(canvas);
    } else {
      window.addEventListener("resize", draw);
    }

    return {
      update: function (nextSeries, nextOpts) {
        series = (nextSeries || []).map(function (v) {
          var f = parseFloat(v);
          return isFinite(f) ? f : null;
        });
        if (nextOpts) {
          if (nextOpts.baseline !== undefined) conf.baseline = nextOpts.baseline;
          if (nextOpts.color) conf.color = nextOpts.color;
          if (nextOpts.fill) conf.fill = nextOpts.fill;
        }
        draw();
      },
      destroy: function () {
        canvas.removeEventListener("mousemove", onMove);
        canvas.removeEventListener("mouseleave", onLeave);
        if (ro) ro.disconnect(); else window.removeEventListener("resize", draw);
      },
    };
  }

  window.EquityChart = EquityChart;
})();
